const legacyAiLiteracyPageCodes = Object.fromEntries(Object.entries(aiLiteracyPageCodeRenames).map(([legacyCode, currentCode]) => [currentCode, legacyCode]));
export function normalizeAiLiteracyPageCode(pageCode) {
    return aiLiteracyPageCodeRenames[pageCode] ?? pageCode;
}
export function getLegacyAiLiteracyPageCode(pageCode) {
    return legacyAiLiteracyPageCodes[pageCode] ?? pageCode;
}
const topicSeeds = aiLiteracyFoundationTopicSeeds;
function findAiLiteracyPageSeed(pageCode) {
    const page = topicSeeds.flatMap((topic) => topic.pages).find((item) => item.code === pageCode);
    if (!page) {
        throw new Error(`AI Literacy preview page not found: ${pageCode}`);
    }
    return page;
}
function reuseAiLiteracyPage(pageCode) {
    const page = findAiLiteracyPageSeed(pageCode);
    return {
        ...page,
        blocks: page.blocks,
    };
}
